<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Row = Record<string, any>;
const tab = ref("continue"); const history = ref<Row[]>([]); const loading = ref(false); const error = ref(""); const settings = ref({ autoplay: false, quality: "服务端默认", subtitle: "服务端默认" });
async function load() { loading.value = true; error.value = ""; try { const result = await http.get<unknown, unknown>("/media/playback/history"); history.value = Array.isArray(result) ? result as Row[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "播放历史加载失败"; } finally { loading.value = false; } }
function progress(item: Row) { const value = Number(item.positionSeconds || item.lastPositionSeconds || 0); const total = Number(item.durationSeconds || 0); return total > 0 ? Math.min(100, Math.round(value / total * 100)) : 0; }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">媒体消费</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理继续观看、播放历史和播放设置，不提供客厅式全屏播放器。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="继续" name="continue"><el-skeleton v-if="loading" :rows="5" animated/><el-empty v-else-if="!history.length" description="暂无可继续内容"/><div v-for="item in history.filter(item => !item.completed).slice(0, 6)" :key="item.id" class="flex items-center gap-4 py-4 border-b last:border-0"><div class="flex h-16 w-24 items-center justify-center rounded bg-[var(--el-fill-color-light)] text-xs">封面</div><div class="min-w-0 flex-1"><div class="font-medium truncate">{{ item.title || item.resourceTitle || item.resourceId || 'Resource' }}</div><div class="mt-1 text-sm text-[var(--el-text-color-secondary)]">{{ item.episodeTitle || item.chapterTitle || item.trackTitle || '继续播放' }} · {{ item.updatedAt || item.lastPlayedAt || '-' }}</div><el-progress :percentage="progress(item)" :show-text="false" class="mt-2"/></div><el-button type="primary" plain>继续</el-button></div></el-tab-pane><el-tab-pane label="历史" name="history"><el-skeleton v-if="loading" :rows="6" animated/><el-empty v-else-if="!history.length" description="暂无播放历史"/><el-table v-else :data="history" stripe><el-table-column prop="resourceTitle" label="Resource" min-width="220"><template #default="{ row }">{{ row.resourceTitle || row.title || row.resourceId || '—' }}</template></el-table-column><el-table-column label="内容位置" min-width="160"><template #default="{ row }">{{ row.episodeTitle || row.chapterTitle || row.trackTitle || '—' }}</template></el-table-column><el-table-column prop="deviceId" label="设备/客户端" min-width="160"/><el-table-column prop="startedAt" label="开始时间" min-width="180"/><el-table-column prop="completed" label="是否完成" width="110"/><el-table-column prop="positionSeconds" label="最后位置" width="110"/><el-table-column label="操作" width="120"><template #default="{ row }"><el-button link :disabled="!row.id">从历史中移除</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="播放列表 / 队列" name="queue"><el-card shadow="never" class="bg-[var(--el-fill-color-lighter)]"><div class="flex items-center justify-between mb-3"><span class="font-medium">当前队列</span><el-button disabled>保存顺序</el-button></div><el-empty description="暂无播放列表或队列；接入队列接口后可拖拽调整顺序"/></el-card></el-tab-pane><el-tab-pane label="播放设置" name="settings"><el-descriptions :column="1" border><el-descriptions-item label="服务端默认画质">{{ settings.quality }}</el-descriptions-item><el-descriptions-item label="服务端字幕策略">{{ settings.subtitle }}</el-descriptions-item></el-descriptions><el-alert class="mt-4" title="仅展示服务端明确支持的默认项" type="info" :closable="false"/><el-switch v-model="settings.autoplay" class="mt-4" active-text="自动播放下一项" disabled/></el-tab-pane></el-tabs></el-card></main></template>
